import{_ as e,a,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"《周易》是怎样的一部书：经、传、注与成书问题","description":"从传世经传、汉代书目与出土材料区分《周易》的文本层次，说明伏羲、文王、周公、孔子的传统归属及其证据边界。","frontmatter":{"title":"《周易》是怎样的一部书：经、传、注与成书问题","description":"从传世经传、汉代书目与出土材料区分《周易》的文本层次，说明伏羲、文王、周公、孔子的传统归属及其证据边界。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"从传世经传、汉代书目与出土材料区分《周易》的文本层次，说明伏羲、文王、周公、孔子的传统归属及其证据边界。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"阿甘正传","link":"/life/personal/media/movies/forrest-gump","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"易经：专题导读与学习地图","link":"/life/personal/yijing/overview"},"next":{"text":"易经：阴阳、卦画与六爻结构","link":"/life/personal/yijing/symbols"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"易经：专题导读与学习地图","link":"/life/personal/yijing/overview"},"next":{"text":"易经：阴阳、卦画与六爻结构","link":"/life/personal/yijing/symbols"}},"headers":[],"relativePath":"life/personal/yijing/text-history.md","filePath":"life/personal/yijing/text-history.md"}'),n={name:"life/personal/yijing/text-history.md"};function d(o,t,l,h,s,p){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="《周易》是怎样的一部书-经、传、注与成书问题" tabindex="-1">《周易》是怎样的一部书：经、传、注与成书问题 <a class="header-anchor" href="#《周易》是怎样的一部书-经、传、注与成书问题" aria-label="Permalink to &quot;《周易》是怎样的一部书：经、传、注与成书问题&quot;">​</a></h1><p>读《周易》，第一件事是认清眼前这句话属于哪一层。卦爻辞、《易传》、王弼或朱熹的注解、今天的白话说明，经常被印在同一页；它们彼此解释，却并非同时写成，更不是同一个人说的话。把层次分开，不会削弱经典，反而能看见一部早期文本怎样持续引出新的问题。</p><p>本文以通行本为阅读入口，涉及作者时分别使用“传统归属”“史书记载”“文本可见”“尚不能确定”等说法。各类证据支持的结论不同，不能只因一句话很古老，就把它当作对更早时代的现场记录。</p><h2 id="先拆开四个常被混用的名称" tabindex="-1">先拆开四个常被混用的名称 <a class="header-anchor" href="#先拆开四个常被混用的名称" aria-label="Permalink to &quot;先拆开四个常被混用的名称&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>本专题采用的含义</th><th>阅读时首先找什么</th></tr></thead><tbody><tr><td>《周易》古经、经文</td><td>六十四卦的卦画、卦名、卦辞、爻题及爻辞等基本文本</td><td>说了什么事，给了什么判断</td></tr><tr><td>《易传》、十翼</td><td>围绕古经形成的七种十篇传文</td><td>如何说明卦爻、宇宙秩序和人的行动</td></tr><tr><td>广义《周易》</td><td>经与传合在一起的经典</td><td>哪些段落是经，哪些是传</td></tr><tr><td>易学</td><td>历代研究、解释和运用《易》的传统</td><td>某种方法由谁提出，有何依据</td></tr></tbody></table><p>日常说“《易经》里讲”，可能指四者中的任意一种。正式做笔记时，应写成“《乾》九三爻辞”“《系辞下》某段”“朱熹《本义》释乾卦”，这样才能讨论同一问题。这里的“经”“传”也不是现代意义上的正文和无关附件：传文后来同样获得经典地位，只是在历史和解释功能上必须分别看。</p><p>通行古经分上经三十卦、下经三十四卦，共六十四卦、三百八十四个爻位。乾、坤另有“用九”“用六”辞，不能因此说它们各有七个爻位。传的七种十篇如何计算，见<a href="/life/personal/yijing/ten-wings">《十翼》逐篇阅读</a>。</p><h2 id="一页书里可能叠着哪些声音" tabindex="-1">一页书里可能叠着哪些声音 <a class="header-anchor" href="#一页书里可能叠着哪些声音" aria-label="Permalink to &quot;一页书里可能叠着哪些声音&quot;">​</a></h2><p>以乾卦为例，可以把同一页重排成如下读书卡：</p><table tabindex="0"><thead><tr><th>层次</th><th>原文或内容</th><th>它在回答的问题</th></tr></thead><tbody><tr><td>卦辞</td><td>“乾，元亨利贞”</td><td>对全卦作什么判断</td></tr><tr><td>爻辞</td><td>“初九，潜龙勿用”</td><td>这一爻呈现何种处境、宜如何行动</td></tr><tr><td>《彖传》</td><td>“大哉乾元，万物资始”</td><td>怎样从天道和生成解释乾卦</td></tr><tr><td>《大象》</td><td>“天行健，君子以自强不息”</td><td>人可从卦象引出什么修养要求</td></tr><tr><td>《文言》</td><td>对四德、六爻与进退的进一步说明</td><td>怎样把简短辞句展开为德行论</td></tr><tr><td>注疏</td><td>解释字义、位置、关系，讨论前说</td><td>哪种理解更能贯通上下文</td></tr></tbody></table><p>“自强不息”出自乾卦《大象》，不是乾的卦辞；“一阴一阳之谓道”出自《系辞上》，不是某卦爻辞。这样的归属看似细小，却决定了一项思想最早在哪个文本层次明确出现。不能用传文较成熟的哲学语言，直接证明所有古经辞句原本就在讲同一套哲学。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B71" target="_blank" rel="noopener noreferrer">原文：乾卦相关解释见《周易本义》卷一</a>。</p><h2 id="传统作者谱系-重要的文化记忆-有限的历史证明" tabindex="-1">传统作者谱系：重要的文化记忆，有限的历史证明 <a class="header-anchor" href="#传统作者谱系-重要的文化记忆-有限的历史证明" aria-label="Permalink to &quot;传统作者谱系：重要的文化记忆，有限的历史证明&quot;">​</a></h2><p>常见的说法是伏羲画卦、文王作卦辞、周公作爻辞、孔子作十翼。读传统注本需要认识这套谱系，但不能把它直接改写成现代著作权登记表。</p><h3 id="伏羲与画卦" tabindex="-1">伏羲与画卦 <a class="header-anchor" href="#伏羲与画卦" aria-label="Permalink to &quot;伏羲与画卦&quot;">​</a></h3><p>《系辞下》讲包牺氏“仰则观象于天，俯则观法于地”，并把八卦的创制联系到观察身体、鸟兽与自然。这是经典内部对于文明起源的说明，表达了取象应与经验世界相连的思想。它不能独自证明某一历史人物在一个可确定年份发明全部卦画，更不能据此安排一张精确到年的易学起源年表。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E7%B9%AB%E8%BE%AD%E4%B8%8B" target="_blank" rel="noopener noreferrer">《系辞下》“古者包牺氏”段</a>。</p><h3 id="文王与周公" tabindex="-1">文王与周公 <a class="header-anchor" href="#文王与周公" aria-label="Permalink to &quot;文王与周公&quot;">​</a></h3><p>《史记·周本纪》记文王被囚羑里，并说“盖益易之八卦为六十四卦”。注意这里的“盖”，也注意《史记》记录此事时已远离商周之际。这个材料可证明汉代历史叙述如何理解文王与《易》的关系，不能直接当作殷末书写现场的证据。<a href="https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7004" target="_blank" rel="noopener noreferrer">《史记》卷四</a>。</p><p>朱熹《本义》把卦辞归文王、爻辞归周公，是需要了解的传统解释框架。但不同古籍对画卦、重卦、系辞的分工并不完全一致。例如《汉书·艺文志》把伏羲、文王、孔子串成“人更三圣，世历三古”的谱系，没有按照现代常见口诀同等列出四位作者。<strong>传统内部本身就存在不同叙述方式。</strong> <a href="https://zh.wikisource.org/wiki/%E6%BC%A2%E6%9B%B8/%E5%8D%B7030" target="_blank" rel="noopener noreferrer">《汉书》卷三十“易”类</a>。</p><h3 id="孔子与十翼" tabindex="-1">孔子与十翼 <a class="header-anchor" href="#孔子与十翼" aria-label="Permalink to &quot;孔子与十翼&quot;">​</a></h3><p>《史记·孔子世家》有“孔子晚而喜易”，并列出彖、系、象、说卦、文言等名称，也记“韦编三绝”。这些是孔子与易学关系的重要传世记载。问题在于：有关系、参与传授、保存相关言论、亲笔完成现存每篇，是四个不同强度的判断。仅有后出的归属记载，不足以把现存十翼每一句都确定为孔子亲笔。<a href="https://zh.wikisource.org/wiki/%E5%8F%B2%E8%A8%98/%E5%8D%B7047" target="_blank" rel="noopener noreferrer">《史记》卷四十七</a>。</p><p>因此，本专题称“《易传》说”或“《文言》说”；在解释传统作者观时才说“传统归于孔子”。各篇的形成时间、内部层次、材料传承仍须分别研究，不以一句“孔子作”封闭讨论，也不把所有相关传统轻率说成毫无意义。</p><h2 id="成书年代-至少包含四个不同问题" tabindex="-1">“成书年代”至少包含四个不同问题 <a class="header-anchor" href="#成书年代-至少包含四个不同问题" aria-label="Permalink to &quot;“成书年代”至少包含四个不同问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>所问年代</th><th>要寻找的证据</th><th>不能顺便推出什么</th></tr></thead><tbody><tr><td>某个故事、词语或占辞何时产生</td><td>语言、制度、历史背景、平行材料</td><td>不能直接确定整部书完成年代</td></tr><tr><td>卦爻辞何时被整理为较稳定的文本</td><td>不同写本的共同部分与差异</td><td>不能确定现存卦序从未变化</td></tr><tr><td>某篇传文何时形成</td><td>引用关系、术语、篇章结构、出土材料</td><td>不能把十翼全部判为同年同作者</td></tr><tr><td>眼前这一抄本何时写成、入墓</td><td>字体、物质检测、墓葬与纪年材料</td><td>不能把抄写时间当作内容创作时间</td></tr></tbody></table><p>本专题采用“分层阅读、分别论证”的做法：卦爻辞保存较早的占筮和社会生活材料，传文围绕它发展解释，注疏再形成各自体系。具体形成过程并不能靠一个简单年代解决。说“《周易》出于西周”时，也必须追问：指早期核心材料、卦爻辞编定，还是连十翼在内的今本？若不限定对象，这句话会造成误解。</p><h2 id="出土材料让哪些问题变得可以比较" tabindex="-1">出土材料让哪些问题变得可以比较 <a class="header-anchor" href="#出土材料让哪些问题变得可以比较" aria-label="Permalink to &quot;出土材料让哪些问题变得可以比较&quot;">​</a></h2><h3 id="马王堆帛书-早期写本与传世本不是同一件东西" tabindex="-1">马王堆帛书：早期写本与传世本不是同一件东西 <a class="header-anchor" href="#马王堆帛书-早期写本与传世本不是同一件东西" aria-label="Permalink to &quot;马王堆帛书：早期写本与传世本不是同一件东西&quot;">​</a></h3><p>马王堆三号汉墓出土的帛书包含《周易》及相关易学文献。其卦序、卦名用字及部分文字与通行本有差异，因此早期传承存在怎样的编排和文本面貌，可以进行实物基础上的讨论。墓葬封闭年代能为随葬文本的存在时间提供界限，但不是该书写成的准确日期。也不能由一个较早抄本推出“它所有字都比后世本正确”。</p><p>此处的稳妥认识只有两层：第一，早期流传的《易》存在可比较的异本；第二，今本的篇目排列与经传关系需要历史说明。关于哪个字更早、哪种卦序更原始，还要逐项论证。相关资料可从<a href="https://www.hnmuseum.com/sites/default/files/statics/zhutishoucang/03%E9%A9%AC%E7%8E%8B%E5%A0%86%E6%B1%89%E5%A2%93%E5%B8%9B%E4%B9%A6%E9%9B%86%E7%B2%B9/BookOnSilk/001.pdf" target="_blank" rel="noopener noreferrer">湖南博物馆《长沙马王堆汉墓帛书概述》</a>及<a href="https://lawdata.com.tw/tw/detail.aspx?no=347194" target="_blank" rel="noopener noreferrer">张家胜关于帛书卦序的研究摘要</a>进入。前者此次能核到检索摘要，PDF正文获取超时；本文不据未读取的影印页作字形校勘。</p><h3 id="上博楚竹书-古文字很重要-来源条件也重要" tabindex="-1">上博楚竹书：古文字很重要，来源条件也重要 <a class="header-anchor" href="#上博楚竹书-古文字很重要-来源条件也重要" aria-label="Permalink to &quot;上博楚竹书：古文字很重要，来源条件也重要&quot;">​</a></h3><p>上海博物馆藏战国楚竹书中有《周易》材料。它为战国时期的文本形态提供了重要线索，但该批竹简由市场购藏，具体出土地点与原始墓葬关系缺乏可完整追溯的科学发掘记录。文字、竹材检测、缀合研究仍有价值；只是不能把它当作“某号墓某层位明确出土”的同类证据。<a href="https://www.shutudo.org/newmaterial/syanhaku" target="_blank" rel="noopener noreferrer">中国出土文献研究会“上博楚简”资料页</a>。</p><p>一个实用习惯是把证据写成两列：“材料实际显示什么”和“我由此推测什么”。例如“有不同卦序”属于可比较现象；“某一卦序由某位圣人创定”则需要额外证据，二者之间不能省略推理过程。</p><h2 id="版本形式也会影响理解" tabindex="-1">版本形式也会影响理解 <a class="header-anchor" href="#版本形式也会影响理解" aria-label="Permalink to &quot;版本形式也会影响理解&quot;">​</a></h2><p>经传合编，适合逐卦学习；经传分编，便于观察两层文字怎样解释同一问题。两种形式都有用途，不能仅凭版面先后判定年代先后。《周易本义》四库本提要详细讨论了后人把《本义》拆附《程传》而改变次序的问题，这提醒我们：<strong>“这是朱熹的书”不等于“这份排版保存了朱熹原有结构”。</strong> <a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)" target="_blank" rel="noopener noreferrer">《周易本义》四库本提要</a>。</p><p>古籍数字化文本还可能有断句、异体字转换和识别错误。本专题引用时以短句为主，通行简体便于阅读，保留“无咎”等常见经文用字；涉及解释分歧时先列原文连续字句，再说明采用哪种断法。单靠搜索命中一句话，不能代替阅读它前后的经、传、注。</p><h2 id="一次可以完成的文本层次练习" tabindex="-1">一次可以完成的文本层次练习 <a class="header-anchor" href="#一次可以完成的文本层次练习" aria-label="Permalink to &quot;一次可以完成的文本层次练习&quot;">​</a></h2><p>取乾卦或坤卦，先抄卦辞和六条爻辞，不抄注解；再用另一种标记补上《彖》《象》《文言》。随后回答三问：哪些意思经文明说了？哪些意思是传文展开的？哪些是注家为解释前两层增添的？</p><p>例如“潜龙勿用”给出形象和行动限制；“龙，德而隐者也”把龙解释成德行与隐居；将它比作今天的新员工暂缓承担高风险职责，则是现代类比。三个层次可以连通，但不能把第三层写成第一层本来就在描写现代职场。</p><p>本篇实际核读了《系辞下》的画卦叙述、《史记》两篇相关段落、《汉书·艺文志》易类，以及《本义》卷一与四库本提要。考古部分仅作文本史入口，没有声称完成帛书、竹简原件或全部整理本的校勘。下一步可读<a href="/life/personal/yijing/commentaries">历代注家怎样解释同一句话</a>，或进入<a href="/life/personal/yijing/reading-practice">经传对读练习</a>。<a href="/life/personal/yijing/overview">返回易经专题</a>。</p>',38)])])}const u=e(n,[["render",d]]);export{f as __pageData,u as default};
